const envelope    = $input.first().json;
const interactive = envelope.message?.interactive ?? {};
const messageText = String(envelope.message?.text ?? '').trim();
const textLower   = messageText.toLowerCase().trim();
const session     = envelope.session ?? {};
const step        = session.current_step ?? 'idle';
const pending     = session.pending_context ?? {};
const botEnabled  = envelope.tenant?.settings?.is_bot_enabled ?? true;
const tz          = envelope.tenant?.timezone ?? 'America/Mexico_City';

// (B4) La revisión de bot pausado se hace después de detectar al admin; ver "MODO ADMIN".


// ── ADMIN: texto directo ────────────────────────────────────
const adminWords = ['#admin', 'admin panel', 'panel admin', 'administrar'];
const wantsAdmin = adminWords.some(w => textLower.includes(w));

const normalize = (v) =>
  String(v ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .trim()
    .replace(/\s+/g, ' ');

const isInt = (v) => /^\d+$/.test(String(v ?? '').trim());

const fmtFull = (iso, timeZone = 'America/Mexico_City') => {
  try {
    return new Intl.DateTimeFormat('es-MX', {
      timeZone,
      weekday: 'short',
      day: '2-digit',
      month: 'short',
      hour: '2-digit',
      minute: '2-digit',
      hour12: true,
    }).format(new Date(iso));
  } catch {
    return '';
  }
};

const normalizedText  = normalize(messageText);
const normalizedWords = normalizedText.replace(/[^a-z0-9: ]+/g, ' ').replace(/\s+/g, ' ').trim();

const getLocalParts = (iso, timeZone = 'America/Mexico_City') => {
  const d = new Date(iso);
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    year: 'numeric',
    month: 'numeric',
    day: 'numeric',
    hour: 'numeric',
    minute: 'numeric',
    hourCycle: 'h23',
  }).formatToParts(d).reduce((acc, p) => {
    if (p.type !== 'literal') acc[p.type] = Number(p.value);
    return acc;
  }, {});

  const weekdayLabel = normalize(new Intl.DateTimeFormat('es-MX', {
    timeZone,
    weekday: 'long',
  }).format(d));

  return {
    year: parts.year,
    month: parts.month,
    day: parts.day,
    hour: parts.hour,
    minute: parts.minute,
    weekday: weekdayLabel,
  };
};

const addLocalDays = (date, days) => new Date(date.getTime() + days * 24 * 60 * 60 * 1000);

const parseSlotRequest = (text, slots, timeZone = 'America/Mexico_City') => {
  if (!text || !Array.isArray(slots) || slots.length === 0) return null;

  const months = {
    enero: 1, febrero: 2, marzo: 3, abril: 4, mayo: 5, junio: 6,
    julio: 7, agosto: 8, septiembre: 9, setiembre: 9, octubre: 10,
    noviembre: 11, diciembre: 12,
  };
  const weekdays = ['domingo', 'lunes', 'martes', 'miercoles', 'jueves', 'viernes', 'sabado'];
  const hasDateWord = /(hoy|manana|pasado manana|lunes|martes|miercoles|jueves|viernes|sabado|domingo|enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre|\d{1,2}[\/-]\d{1,2})/.test(text);

  let requestedDay = null;
  let requestedMonth = null;
  let requestedWeekday = weekdays.find((w) => text.includes(w)) ?? null;

  const longDate = text.match(/\b(\d{1,2})\s*(?:de\s+)?(enero|febrero|marzo|abril|mayo|junio|julio|agosto|septiembre|setiembre|octubre|noviembre|diciembre)\b/);
  if (longDate) {
    requestedDay = Number(longDate[1]);
    requestedMonth = months[longDate[2]];
  }

  const slashDate = text.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
  if (!longDate && slashDate) {
    requestedDay = Number(slashDate[1]);
    requestedMonth = Number(slashDate[2]);
  }

  const nowParts = getLocalParts(new Date().toISOString(), timeZone);
  if (text.includes('pasado manana')) {
    const target = getLocalParts(addLocalDays(new Date(), 2).toISOString(), timeZone);
    requestedDay = target.day;
    requestedMonth = target.month;
  } else if (text.includes('manana')) {
    const target = getLocalParts(addLocalDays(new Date(), 1).toISOString(), timeZone);
    requestedDay = target.day;
    requestedMonth = target.month;
  } else if (text.includes('hoy')) {
    requestedDay = nowParts.day;
    requestedMonth = nowParts.month;
  }

  const timeCandidates = [];
  const pushTime = (hourRaw, minuteRaw, meridianRaw, dayPartRaw) => {
    let hour = Number(hourRaw);
    const minute = minuteRaw == null || minuteRaw === '' ? 0 : Number(minuteRaw);
    const meridian = normalize(meridianRaw ?? '');
    const dayPart = normalize(dayPartRaw ?? '');
    if (!Number.isFinite(hour) || hour < 0 || hour > 23 || !Number.isFinite(minute) || minute > 59) return;

    if (meridian === 'pm' && hour < 12) hour += 12;
    if (meridian === 'am' && hour === 12) hour = 0;
    if ((dayPart === 'tarde' || dayPart === 'noche') && hour < 12) hour += 12;
    if (dayPart === 'manana' && hour === 12) hour = 0;
    timeCandidates.push({ hour, minute });
  };

  let m;
  if ((m = text.match(/(?:a las|alas|de las|las)\s+(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/))) pushTime(m[1], m[2], m[3], null);
  if ((m = text.match(/\b(\d{1,2}):(\d{2})\s*(am|pm)?\b/))) pushTime(m[1], m[2], m[3], null);
  if ((m = text.match(/\b(\d{1,2})\s*(am|pm)\b/))) pushTime(m[1], null, m[2], null);
  if ((m = text.match(/\b(\d{1,2})\s+de la\s+(manana|tarde|noche)\b/))) pushTime(m[1], null, null, m[2]);

  if (timeCandidates.length === 0) return null;

  const ranked = slots
    .map((slot, index) => {
      const p = getLocalParts(slot.start, timeZone);
      let score = 0;
      const timeMatch = timeCandidates.some((t) => t.hour === p.hour && t.minute === p.minute);
      if (!timeMatch) return null;
      score += 20;
      if (requestedDay != null) score += p.day === requestedDay ? 12 : -100;
      if (requestedMonth != null) score += p.month === requestedMonth ? 12 : -100;
      if (requestedWeekday) score += p.weekday === requestedWeekday ? 6 : -20;
      if (!hasDateWord) score += Math.max(0, 5 - index);
      return { slot, index, score };
    })
    .filter(Boolean)
    .filter((r) => r.score >= 20)
    .sort((a, b) => (b.score - a.score) || (a.index - b.index));

  return ranked[0]?.slot ?? null;
};
const availableSlots  = Array.isArray(pending.available_slots) ? pending.available_slots : [];
const apptsForAction  = Array.isArray(pending.appointments_for_action) ? pending.appointments_for_action : [];
const activePatientId = session.active_patient_id || envelope.patient?.active_patient_id || null;
const activeServiceId = session.active_service_id || null;
const activeProviderId = session.active_provider_id || pending.active_provider_id || pending.provider_id || null;

const menuWords    = ['hola', 'ola', 'buen dia', 'buenos dias', 'buenas tardes', 'buenas noches', 'menu', 'menú', 'inicio', 'start', 'ayuda', 'help'];
const cancelWords  = ['cancelar', 'cancela', 'cancel', 'dar de baja'];
const reschWords   = ['reagendar', 'reprogramar', 'cambiar cita', 'mover cita', 'reschedule'];
const bookWords    = ['agendar', 'reservar', 'quiero cita', 'necesito cita', 'nueva cita', 'consulta', 'consultar', 'doctor', 'doctora', 'medico', 'médico', 'especialista', 'neumologo', 'neumólogo', 'cardiologo', 'cardiólogo', 'pediatra', 'traumatologo', 'traumatólogo', 'book'];
const catalogWords = ['servicio', 'servicios', 'precio', 'precios', 'tratamiento', 'tratamientos'];

// (B1) Palabras completas: evita que "Paola", "Yolanda" o "Nicolás" cuenten como "hola".
const toWords = (v) => normalize(v).replace(/[^a-z0-9: ]+/g, ' ').replace(/\s+/g, ' ').trim();
const hasWord = (phrase) => { const p = toWords(phrase); return p.length > 0 && (' ' + normalizedWords + ' ').includes(' ' + p + ' '); };
// Mientras se espera texto libre (nombre del paciente), solo cuenta si el mensaje es SOLO el saludo.
const freeTextStep   = step === 'awaiting_patient_name';
const wantsMenu      = freeTextStep
  ? menuWords.some(w => normalizedWords === toWords(w))
  : menuWords.some(hasWord);
const wantsCancel    = cancelWords.some(w => normalizedText.includes(normalize(w)));
const wantsResched   = reschWords.some(w => normalizedText.includes(normalize(w)));
const wantsBooking   = bookWords.some(w => normalizedText.includes(normalize(w)));
const wantsCatalog   = catalogWords.some(w => normalizedText.includes(normalize(w)));

const cleanToMenu = () => [{
  json: {
    ...envelope,
    patient: {
      ...(envelope.patient ?? {}),
      active_patient_id: null,
    },
    session: {
      ...session,
      current_step: 'idle',
      pending_context: {},
      pending_slot_start: null,
      pending_slot_end: null,
      active_service_id: null,
      active_patient_id: null,
      active_provider_id: null,
    },
    _session_update: {
      current_step: 'idle',
      pending_context: {},
      pending_slot_start: null,
      pending_slot_end: null,
      active_service_id: null,
      active_patient_id: null,
      active_provider_id: null,
    },
    _route: 'welcome_menu',
  }
}];
const consumeCurrentInput = () => ({
  _input_consumed: true,
  _consumed_message_id: envelope.message?.message_id ?? null,
});

const routeToCatalog = (extra = {}) => [{
  json: {
    ...envelope,
    ...extra,
    _route: 'catalog_engine',
  }
}];

const routeToPatientManager = (extra = {}) => [{
  json: {
    ...envelope,
    ...extra,
    _route: 'patient_manager',
  }
}];

const routeToAvailability = (extra = {}) => [{
  json: {
    ...envelope,
    ...extra,
    _route: 'availability',
  }
}];

const routeToBooking = (slot, extra = {}) => [{
  json: {
    ...envelope,
    ...extra,
    _selected_slot: slot,
    session: {
      ...session,
      current_step: 'confirming',
      pending_slot_start: slot?.start ?? null,
      pending_slot_end: slot?.end ?? null,
    },
    _session_update: {
      current_step: 'confirming',
      pending_slot_start: slot?.start ?? null,
      pending_slot_end: slot?.end ?? null,
      active_provider_id: activeProviderId,
    },
    _route: 'booking',
  }
}];

// ── MODO ADMIN (B3) y BOT PAUSADO (B4) ───────────────────────────────
// CF-16 deja current_step = 'admin_mode' al verificar al admin. Todo lo que escriba se va al panel
// hasta que escriba "salir" (o la sesión expire por inactividad).
const exitAdminWords = ['salir', 'exit', 'menu', 'inicio', 'hola'];
if (step === 'admin_mode') {
  if (exitAdminWords.includes(normalizedWords)) return cleanToMenu();
  return [{ json: { ...envelope, _route: 'admin' } }];
}
if (!botEnabled && !wantsAdmin) {
  return [{ json: { ...envelope, _route: 'bot_disabled' } }];
}

// ── PRIORIDAD 1: INTERACTIVOS ────────────────────────────────────────
if (interactive.id) {
  const id = interactive.id;

  if (id === 'CF:START' || id === 'CF:MENU') {
    return cleanToMenu();
  }

  if (id.startsWith('CF:PAT:') || id === 'CF:NEWPAT') {
    return routeToPatientManager();
  }

  if (id.startsWith('CF:SERV:')) {
    const sid = id.replace('CF:SERV:', '').trim();
    return routeToCatalog({
      session: { ...session, active_service_id: sid || null },
    });
  }

  if (id.startsWith('CF:SLOT:')) {
    const decoded = decodeURIComponent(id.replace('CF:SLOT:', ''));
    if (!activeServiceId) return routeToCatalog({ _repair_reason: 'slot_without_service' });
    if (!activePatientId) return routeToPatientManager({ _repair_reason: 'slot_without_patient' });
    return routeToBooking({ start: decoded, end: null, source: 'interactive' });
  }

  if (id.startsWith('CF:CANCEL:')) {
    return [{
      json: {
        ...envelope,
        _route: 'cancel_reschedule',
        _cr_action: 'cancel',
        _cr_appointment_id: id.replace('CF:CANCEL:', ''),
      }
    }];
  }

  if (id.startsWith('CF:RESCH:')) {
    return [{
      json: {
        ...envelope,
        _route: 'cancel_reschedule',
        _cr_action: 'reschedule',
        _cr_appointment_id: id.replace('CF:RESCH:', ''),
      }
    }];
  }

  if (id.startsWith('CF:ADMIN:')) {
    return [{ json: { ...envelope, _route: 'admin' } }];
  }
}


if (wantsAdmin) {
  return [{ json: { ...envelope, _route: 'admin' } }];
}

// ── PRIORIDAD 2: COMANDOS GLOBALES ───────────────────────────────────
if (wantsCancel) {
  return [{
    json: {
      ...envelope,
      _route: 'cancel_reschedule',
      _cr_action: 'cancel_lookup',
    }
  }];
}

if (wantsResched) {
  return [{
    json: {
      ...envelope,
      _route: 'cancel_reschedule',
      _cr_action: 'reschedule_lookup',
    }
  }];
}

if (wantsMenu && !wantsBooking && !wantsCatalog && !normalizedText.includes('cita')) {
  return cleanToMenu();
}

// ── PRIORIDAD 3: ESTADO DE SESIÓN ────────────────────────────────────
if (['select_patient', 'awaiting_patient_name'].includes(step)) {
  return routeToPatientManager();
}

if (step === 'select_service') {
  const currentMessageId = envelope.message?.message_id ?? null;
  const catalogPromptMessageId = pending.catalog_prompt_message_id ?? null;

  const isSameMessageThatOpenedCatalog =
    !!currentMessageId &&
    !!catalogPromptMessageId &&
    currentMessageId === catalogPromptMessageId;

  return routeToCatalog(
    isSameMessageThatOpenedCatalog
      ? {
          _input_consumed: true,
          _consumed_message_id: currentMessageId,
          _catalog_origin: 'select_service_same_message_guard',
        }
      : {}
  );
}

if (step === 'select_provider') {
  return routeToCatalog();
}

if (step === 'select_slot') {
  if (!activeServiceId) return routeToCatalog({ _repair_reason: 'missing_service_before_slots' });
  if (!activePatientId) return routeToPatientManager({ _repair_reason: 'missing_patient_before_slots' });
  return routeToAvailability();
}

if (step === 'awaiting_slot_selection') {
  let slot = null;

  if (isInt(messageText)) {
    const idx = Number(messageText) - 1;
    if (idx >= 0 && idx < availableSlots.length) {
      slot = availableSlots[idx];
    }
  }


  if (!slot) {
    return routeToAvailability({ _slot_selection_invalid: true });
  }

  if (!activeServiceId) return routeToCatalog({ _repair_reason: 'slot_selection_without_service' });
  if (!activePatientId) return routeToPatientManager({ _repair_reason: 'slot_selection_without_patient' });

  return routeToBooking(slot);
}

if (step === 'select_cancel_appointment' || step === 'select_reschedule_appointment') {
  let appt = null;
  if (isInt(messageText)) {
    const idx = Number(messageText) - 1;
    if (idx >= 0 && idx < apptsForAction.length) {
      appt = apptsForAction[idx];
    }
  }

  if (!appt && normalizedText && apptsForAction.length > 0) {
    appt = apptsForAction.find((a) => {
      const label = normalize(fmtFull(a.start_at, tz));
      return normalizedText === label || label.includes(normalizedText) || normalizedText.includes(label);
    }) ?? null;
  }

  const isCancel = step === 'select_cancel_appointment';
  if (!appt) {
    return [{
      json: {
        ...envelope,
        _route: 'cancel_reschedule',
        _cr_action: isCancel ? 'cancel_lookup' : 'reschedule_lookup',
        _appointment_selection_invalid: true,
      }
    }];
  }

  return [{
    json: {
      ...envelope,
      _route: 'cancel_reschedule',
      _cr_action: isCancel ? 'cancel' : 'reschedule',
      _cr_appointment_id: appt.id,
      _selected_appointment: appt,
    }
  }];
}

if (step === 'confirming') {
  if (!activeServiceId) return routeToCatalog({ _repair_reason: 'confirming_without_service' });
  if (!activePatientId) return routeToPatientManager({ _repair_reason: 'confirming_without_patient' });
  return [{ json: { ...envelope, _route: 'booking' } }];
}

// ── PRIORIDAD 4: TEXTO LIBRE ─────────────────────────────────────────
if (wantsBooking) {
  return activeServiceId
    ? (activePatientId ? routeToAvailability() : routeToPatientManager())
    : routeToCatalog({
        ...consumeCurrentInput(),
        _catalog_origin: 'text_booking',
      });
}

if (wantsCatalog || normalizedText.includes('cita')) {
  return routeToCatalog({
    _catalog_origin: 'text_catalog',
  });
}

if (isInt(messageText) && step === 'idle') {
  const n = Number(messageText);

  // 1 = Agendar cita
  if (n === 1) {
    return routeToCatalog({
      ...consumeCurrentInput(),
      _catalog_origin: 'main_menu_booking',
    });
  }

  // 2 = Ver servicios
  if (n === 2) {
    return routeToCatalog({
      ...consumeCurrentInput(),
      _catalog_origin: 'main_menu_catalog',
    });
  }

  // 3 = FAQ
  if (n === 3) {
    return [{
      json: {
        ...envelope,
        _route: 'faq',
        ...consumeCurrentInput(),
      }
    }];
  }
}

return [{ json: { ...envelope, _route: 'intent_helper' } }];

const e       = $input.first().json;
const name    = e.user?.wa_name ?? '';
const clinic  = e.tenant?.name  ?? 'nuestra clínica';
const welcome = e.tenant?.settings?.welcome_message;

// ── Mensaje determinístico (siempre funciona aunque GROQ falle) ──────────
const deterministicIntro = welcome
  ?? `👋 Hola${name ? ' ' + name : ''}! Bienvenido/a a *${clinic}*. ¿En qué puedo ayudarte hoy?`;

const menuOptions = '\n\n1. 📅 Agendar cita\n2. 🦷 Ver servicios\n3. ❓ Preguntas frecuentes\n\n_Responde con el número o escribe tu opción._';

// ── Prompt GROQ ──────────────────────────────────────────────────────────
const system =
  `Eres el asistente de WhatsApp de "${clinic}". ` +
  `Reescribe el siguiente saludo de bienvenida con un tono más cálido, natural y humano. ` +
  `REGLAS ESTRICTAS:\n` +
  `- Máximo 2 líneas de texto\n` +
  `- Conserva el nombre de la clínica exactamente como aparece\n` +
  (name ? `- Puedes usar el nombre "${name}" para personalizar\n` : '') +
  `- Usa 1-2 emojis apropiados. No seas formal ni robótico\n` +
  `- Responde SOLO con el saludo, sin menú ni opciones numeradas`;

return [{
  json: {
    ...e,
    _fallback_body: deterministicIntro + menuOptions,
    _menu_options:  menuOptions,
    _outbound: {
      type: 'text',
      body: deterministicIntro + menuOptions
    },
    _groq_messages: [
      { role: 'system', content: system },
      { role: 'user',   content: deterministicIntro }
    ]
  }
}];

const e      = $input.first().json;
const clinic = e.tenant?.name ?? 'nuestra clínica';
const msgTxt = String(e.message?.text ?? '').trim();

const deterministicBody =
  '🤔 No entendí tu mensaje.\n\n¿Te ayudo con algo?\n\n' +
  '1. 📅 Agendar cita\n2. 🦷 Ver servicios\n3. ❓ Preguntas\n\n' +
  '_Responde con el número o escribe tu opción_';

const system =
  `Eres el asistente de WhatsApp de "${clinic}". ` +
  `El usuario escribió algo que no entendiste. ` +
  `Construye un mensaje amable que reconozca que no entendiste ` +
  `y ofrezca ayuda de forma natural. ` +
  `REGLAS:\n` +
  `- Máximo 2 líneas\n` +
  `- Tono amigable, no robótico\n` +
  `- No uses frases genéricas como "¿En qué puedo ayudarte?"\n` +
  `- 1 emoji máximo\n` +
  `- Responde SOLO el texto introductorio, sin opciones numeradas`;

const userMsg = msgTxt
  ? `El usuario escribió: "${msgTxt}". No pude entender su intención.`
  : 'El usuario envió un mensaje que no pude clasificar.';

return [{
  json: {
    ...e,
    _fallback_body: deterministicBody,
    _menu_options:  '\n\n1. 📅 Agendar cita\n2. 🦷 Ver servicios\n3. ❓ Preguntas\n\n_Responde con el número o escribe tu opción_',
    _outbound: { type: 'text', body: deterministicBody },
    _groq_messages: [
      { role: 'system', content: system },
      { role: 'user',   content: userMsg }
    ]
  }
}];

const e = $input.first().json;
const msgs = {
  admin:       '⚙️ Panel de administración próximamente.',
  bot_disabled: null
};
const body = msgs[e._route];
if (!body) return [{ json: { ...e, _outbound: null } }];
return [{ json: { ...e, _outbound: { type:'text',
  body: body + '\n\n¿En qué más puedo ayudarte?\n\n1. 📅 Agendar cita'
}}}];

// Supabase return=minimal → vacío. Recuperar desde Build Welcome Menu.
const e = $('Build Welcome Menu').item.json;
return [{ json: {
  ...e,
  _session_update: undefined
} }];

// Recuperar contexto del nodo anterior en la cadena
// Recover Envelope — Menú ya tiene el envelope limpio con _fallback_body y _menu_options
const ctx      = $('Recover Envelope — Menú').item.json;
const groqResp = $input.first().json;

let aiIntro = null;
try {
  aiIntro = String(groqResp?.choices?.[0]?.message?.content ?? '').trim();
} catch (_) {}

// Validar: debe tener contenido mínimo y no incluir opciones numeradas
const isValid = aiIntro &&
  aiIntro.length >= 15 &&
  aiIntro.length <= 300 &&
  !/^\d+\./.test(aiIntro);  // no debe empezar con "1."

const finalBody = isValid
  ? aiIntro + (ctx._menu_options ?? '')
  : ctx._fallback_body;

return [{
  json: {
    ...ctx,
    _groq_messages:  undefined,
    _fallback_body:  undefined,
    _menu_options:   undefined,
    _outbound: { type: 'text', body: finalBody }
  }
}];

const ctx      = $('Build Fallback').item.json;
const groqResp = $input.first().json;

let aiIntro = null;
try {
  aiIntro = String(groqResp?.choices?.[0]?.message?.content ?? '').trim();
} catch (_) {}

const isValid = aiIntro &&
  aiIntro.length >= 10 &&
  aiIntro.length <= 200 &&
  !/^\d+\./.test(aiIntro);

const finalBody = isValid
  ? aiIntro + (ctx._menu_options ?? '')
  : ctx._fallback_body;

return [{
  json: {
    ...ctx,
    _groq_messages: undefined,
    _fallback_body: undefined,
    _menu_options:  undefined,
    _outbound: { type: 'text', body: finalBody }
  }
}];
